// Writes src/shared/api/chat-event-payloads.generated.ts from the vendored Model Plane golden
// (src/shared/api/contracts/sse-event-payloads.json, WS12 S7): the payload type of each ChatEvent the
// golden describes. A key the golden marks `always` is required, one it marks `optional` may be
// absent, and a key the golden types more than one way becomes a union.
//
//   node scripts/gen-chat-event-types.mjs           write the generated file
//   node scripts/gen-chat-event-types.mjs --check   exit 1 when the checked-in file is stale
//
// The check reads the file with CRLF folded to LF, so a checkout that converts line endings is not
// reported as stale. The SPA's read checker (chat-event-contract.test.ts) runs the check.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const GOLDEN = resolve(here, '../src/shared/api/contracts/sse-event-payloads.json')
const OUTPUT = resolve(here, '../src/shared/api/chat-event-payloads.generated.ts')

const TS_TYPES = {
  string: 'string',
  integer: 'number',
  number: 'number',
  boolean: 'boolean',
  null: 'null',
  object: 'Record<string, unknown>',
  array: 'unknown[]',
}

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/

function propertyName(key) {
  return IDENTIFIER.test(key) ? key : JSON.stringify(key)
}

function typeOf(event, key, types) {
  if (types.length === 0) throw new Error(`${event}.${key}: the golden lists no type`)
  // `null` reads last, as in `string | null`, whatever order the golden lists it in.
  const ordered = [...types.filter((type) => type !== 'null'), ...types.filter((type) => type === 'null')]
  return ordered
    .map((type) => {
      if (!Object.hasOwn(TS_TYPES, type)) throw new Error(`${event}.${key}: the golden names an unknown type "${type}"`)
      return TS_TYPES[type]
    })
    .join(' | ')
}

function render(golden) {
  const lines = [
    '// Generated by scripts/gen-chat-event-types.mjs from src/shared/api/contracts/sse-event-payloads.json.',
    '// Do not edit by hand: run `pnpm gen:chat-events` after the golden changes.',
    '//',
    '// The payload of each ChatEvent the Model Plane golden describes (WS12 S7). A key the golden marks',
    '// `always` is required; one it marks `optional` may be absent.',
    '',
    'export type ChatEventPayloads = {',
  ]
  for (const event of Object.keys(golden.events).sort()) {
    const { variants, keys } = golden.events[event]
    if (variants.length > 0) lines.push(`  /** Rust variants: ${variants.join(', ')}. */`)
    lines.push(`  ${propertyName(event)}: {`)
    for (const key of Object.keys(keys).sort()) {
      const { types, presence } = keys[key]
      if (presence !== 'always' && presence !== 'optional') {
        throw new Error(`${event}.${key}: the golden names an unknown presence "${presence}"`)
      }
      const optional = presence === 'optional' ? '?' : ''
      lines.push(`    ${propertyName(key)}${optional}: ${typeOf(event, key, types)}`)
    }
    lines.push('  }')
  }
  lines.push('}', '')
  return lines.join('\n')
}

const rendered = render(JSON.parse(readFileSync(GOLDEN, 'utf8')))

if (process.argv.includes('--check')) {
  let current = ''
  try {
    current = readFileSync(OUTPUT, 'utf8')
  } catch {
    current = ''
  }
  if (current.replace(/\r\n/g, '\n') !== rendered) {
    console.error('chat-event-payloads.generated.ts is stale against the golden: run pnpm gen:chat-events')
    process.exit(1)
  }
  console.log('chat-event-payloads.generated.ts matches the golden')
} else {
  writeFileSync(OUTPUT, rendered)
  console.log('wrote src/shared/api/chat-event-payloads.generated.ts')
}
